"""Run measured baselines, stress tests and ablations; preserve all configurations."""
import json
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'backend'))
from app.research import experiment
from app.schemas import ExperimentConfig

def main():
    configs=[('clean',ExperimentConfig(seed=941,count=400,missing=0,noise=0,corruption=0)),('missing-10',ExperimentConfig(seed=942,count=400,missing=.1)),('missing-20',ExperimentConfig(seed=943,count=400,missing=.2)),('clock-noise',ExperimentConfig(seed=944,count=400,noise=20)),('identity-conflicts',ExperimentConfig(seed=945,count=400,corruption=.25)),('compound',ExperimentConfig(seed=946,count=400,faults=3))]
    output=Path(__file__).parent/'results';output.mkdir(exist_ok=True)
    reports={name:experiment(config,ablations=True) for name,config in configs}
    (output/'benchmark.json').write_text(json.dumps(reports,indent=2))
    lines=['# Measured synthetic benchmark','', 'Generated by `python research/run_experiments.py`. Latency is machine-dependent. No clinical validation or statistical significance claim.','', '| Configuration | Method | Precision | Recall | Unsafe / all | Abstention | ms/sample |','|---|---|---:|---:|---:|---:|---:|']
    for name,report in reports.items():
        for m in report['results']:
            lines.append(f'| {name} | {m["method"]} | {m["precision"]:.3f} | {m["recall"]:.3f} | {m["unsafe"]:.3f} | {m["abstention"]:.3f} | {m["latency"]:.3f} |')
    lines+=['','## Limitations','','Shared synthetic generator families can favor explicit rules. These results establish repeatability and characterize safety/coverage tradeoffs, not hospital performance. No learned model is trained. Separate seeds provide independent draws but do not remove template-family overlap. Root-cause accuracy uses at-least-one-cause overlap, which is weaker than exact reconstruction. Review workload is flagged-or-abstained fraction. Detection latency in the operational demo is a configured offset; benchmark latency is actual processing time.']
    (output/'benchmark.md').write_text('\n'.join(lines)+'\n')
    print(f'Wrote {len(reports)} measured experiment configurations to {output}')
if __name__=='__main__':main()
